CREATE TABLE storage_connections (
    -- Generated by the app, because the encrypted secret is bound to this ID.
    id                uuid PRIMARY KEY,
    user_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider          text NOT NULL CHECK (provider IN ('s3', 'google_drive')),
    name              text NOT NULL,
    -- Details that aren't secret, such as the endpoint and bucket.
    settings          jsonb NOT NULL,
    -- AES-256-GCM. The key ID says which key sealed it, so keys can be rotated.
    secret_key_id     text NOT NULL,
    secret_ciphertext bytea NOT NULL,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (user_id, name)
);

-- +goose Down
DROP TABLE storage_connections;
